#!/usr/bin/env bash
# Run REST2 run directories one after another on a GPU pool, waiting for the pool to be idle first.
#
#   scripts/run_queue.sh <run-dir> [<run-dir> ...]      e.g. test/4LRH/REST2-test 4LRH/REST2-run1
#
# Each <run-dir> holds the run.sh generated by build-md; its output goes to <run-dir>/run.out.
# A run whose remd_records/REST2_prod1.out already says "run_status: completed" is skipped, and
# run.sh resumes an interrupted stage from its checkpoint, so re-running the queue is safe.
#
# ENV: GPUS=0,1,2,3,4,5,6,7  WAIT_FOR_GPUS=1
#      MPS=0  set 1 when ranks > GPUs (md-tools refuses >1 worker per GPU without MPS). The daemon is
#             started on $GPUS with a private pipe dir, so only processes launched from here join
#             it; the clients then see the daemon's devices renumbered 0..n-1.
#      GPU_UTIL_MAX=15 (% util below which a GPU is idle)
#      GPU_MEM_MAX=20000 (MiB used below which a GPU is idle)  GPU_POLL=60  GPU_STABLE=3
# sbrinz is a shared login node: a GPU counts as idle only when ANOTHER user's job is not
# loading it. Our 8 ranks need only a few GiB each on a 143 GB H200.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
GPUS="${GPUS:-0,1,2,3,4,5,6,7}"
WAIT_FOR_GPUS="${WAIT_FOR_GPUS:-1}"
GPU_UTIL_MAX="${GPU_UTIL_MAX:-15}"
GPU_MEM_MAX="${GPU_MEM_MAX:-20000}"
GPU_POLL="${GPU_POLL:-60}"
GPU_STABLE="${GPU_STABLE:-3}"
MPS="${MPS:-0}"

say() { printf '[%s] %s\n' "$(date '+%F %T')" "$*"; }

export MAMBA_ROOT_PREFIX=/scicore/home/lill0000/popa0002/software/md-stack
eval "$(/scicore/home/lill0000/popa0002/software/md-stack/bin/micromamba shell hook -s bash)"
micromamba activate openmm-env
export MD_DATA="${MD_DATA:-/scicore/home/lill0000/popa0002/md-data}"

pool_idle() {
  local g u m
  for g in ${GPUS//,/ }; do
    read -r u m < <(nvidia-smi -i "$g" --query-gpu=utilization.gpu,memory.used \
                      --format=csv,noheader,nounits | tr -d ',')
    [ "${u:-100}" -lt "$GPU_UTIL_MAX" ] && [ "${m:-999999}" -lt "$GPU_MEM_MAX" ] || return 1
  done
}

wait_for_pool() {
  [ "$WAIT_FOR_GPUS" = 1 ] || { say "WAIT_FOR_GPUS=0: not waiting"; return; }
  local streak=0
  say "waiting for GPUs $GPUS (util < $GPU_UTIL_MAX %, mem < $GPU_MEM_MAX MiB, $GPU_STABLE checks ${GPU_POLL}s apart)"
  while :; do
    if pool_idle; then
      streak=$((streak + 1)); say "  idle check $streak/$GPU_STABLE"
      [ "$streak" -ge "$GPU_STABLE" ] && return
    else
      streak=0
    fi
    sleep "$GPU_POLL"
  done
}

CLIENT_GPUS="$GPUS"
if [ "$MPS" = 1 ]; then
  export CUDA_MPS_PIPE_DIRECTORY="$HOME/.cache/folc-mps/pipe"
  export CUDA_MPS_LOG_DIRECTORY="$HOME/.cache/folc-mps/log"
  mkdir -p "$CUDA_MPS_PIPE_DIRECTORY" "$CUDA_MPS_LOG_DIRECTORY"
  if [ -S "$CUDA_MPS_PIPE_DIRECTORY/control" ] && echo get_server_list | nvidia-cuda-mps-control >/dev/null 2>&1; then
    say "MPS: daemon already running ($CUDA_MPS_PIPE_DIRECTORY)"
  else
    CUDA_DEVICE_ORDER=PCI_BUS_ID CUDA_VISIBLE_DEVICES="$GPUS" nvidia-cuda-mps-control -d \
      || { say "MPS: could not start the daemon"; exit 1; }
    say "MPS: daemon started on GPUs $GPUS ($CUDA_MPS_PIPE_DIRECTORY)"
  fi
  n=$(awk -F, '{print NF}' <<<"$GPUS")
  CLIENT_GPUS=$(seq -s, 0 $((n - 1)))
fi

for d in "$@"; do
  dir="$ROOT/$d"
  [ -x "$dir/run.sh" ] || { say "SKIP $d: no run.sh"; continue; }
  if grep -q '^run_status: completed' "$dir/remd_records/REST2_prod1.out" 2>/dev/null; then
    say "SKIP $d: already completed"; continue
  fi
  wait_for_pool
  say "RUN  $d on GPUs $GPUS (clients see $CLIENT_GPUS, MPS=$MPS) -> $d/run.out"
  ( cd "$dir" && CUDA_DEVICE_ORDER=PCI_BUS_ID CUDA_VISIBLE_DEVICES="$CLIENT_GPUS" ./run.sh ) >>"$dir/run.out" 2>&1
  say "DONE $d rc=$?"
done
say "queue finished"
